package com.healthcompanion.ai; import com.healthcompanion.domain.KnowledgeChunk; import com.healthcompanion.repository.KnowledgeChunkRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class MedicalKnowledgeIngestionService {private final KnowledgeChunkRepository chunks;private final EmbeddingGateway embeddings;private final PgVectorStore vectors;public MedicalKnowledgeIngestionService(KnowledgeChunkRepository c,EmbeddingGateway e,PgVectorStore v){chunks=c;embeddings=e;vectors=v;}@Transactional public int ingest(String source,String topic,String language,String version,String content){int n=0;for(int from=0;from<content.length();from+=2400){var c=new KnowledgeChunk();c.source=source;c.topic=topic;c.language=language;c.version=version;c.chunkIndex=n++;c.content=content.substring(from,Math.min(from+3000,content.length()));c.embeddingProfile=embeddings.profile();c=chunks.save(c);vectors.storeKnowledgeEmbedding(c.id,embeddings.embed(c.content),c.embeddingProfile);}return n;}}
